#include "probe_helpers.hpp"
#include <algorithm>
#include <tuple>
// Host launch timing with exactly 2..256 live compiled bindings. Each output
// has a different scalar increment so the compiler cannot merge the nodes.
int main(int argc,char**argv){
 if(argc!=2)return 1;
 std::string root=argv[1];std::ofstream log(root+"/bindings.jsonl");ck(synInitialize(),"initialize");synDeviceId dev;ck(synDeviceAcquireByModuleId(&dev,gaudi_experiment_module()),"acquire");synStreamHandle stream;ck(synStreamCreateGeneric(&stream,dev,0),"stream");synEventHandle start,end;ck(synEventCreate(&start,dev,EVENT_COLLECT_TIME),"start");ck(synEventCreate(&end,dev,EVENT_COLLECT_TIME),"end");
 std::vector<std::tuple<int,int,bool,int>>cases;for(int count:{2,8,32,128,256})cases.emplace_back(count,6144,false,0);for(int width:{64,262144})for(int count:{2,32})cases.emplace_back(count,width,false,0);for(int count:{2,8,32,128,256})cases.emplace_back(count,6144,true,255);for(int nodes:{1,2,8,32,64,128,256})cases.emplace_back(2,6144,true,nodes);
 for(auto shape:cases){int count,width,nodes;bool controlled;std::tie(count,width,controlled,nodes)=shape;int total=controlled?nodes+1:count;std::string tag=(controlled?"chain-":"fanout-")+std::to_string(count)+"-n"+std::to_string(width)+"-nodes"+std::to_string(total-1);synGraphHandle graph;ck(synGraphCreate(&graph,synDeviceGaudi2),"graph");std::vector<synTensor>tensors(total);std::vector<synSectionHandle>sections(total);std::vector<std::string>names;names.reserve(total);std::vector<int>ports;
  for(int i=0;i<total;++i){names.push_back("v"+std::to_string(i));if(!controlled||i==0||i==total-1||i<=count-2){ports.push_back(i);ck(synSectionCreate(&sections[i],0,graph),"section");ck(synSectionSetPersistent(sections[i],true),"persistent");}synTensorDescriptor d{};d.m_name=names.back().c_str();d.m_dataType=syn_type_single;d.m_dims=2;d.m_sizes[0]=d.m_minSizes[0]=width;d.m_sizes[1]=d.m_minSizes[1]=1;ck(synTensorCreate(&tensors[i],&d,sections[i],0),"tensor");}
  for(int i=1;i<total;++i){float increment=(controlled?1:i)*.03125f;ck(synNodeCreate(graph,&tensors[controlled?i-1:0],&tensors[i],1,1,&increment,4,"gk_native_graph_affine_f32_v1",("node"+std::to_string(i)).c_str(),nullptr,nullptr),"node");}
  synRecipeHandle recipe;ck(synGraphCompile(&recipe,graph,(root+'/'+tag).c_str(),nullptr),"compile");uint32_t live=0;ck(synTensorRetrieveLaunchAmount(recipe,&live),"live bindings");if(live!=uint32_t(count))return 4;std::vector<const char*>cnames;for(int index:ports)cnames.push_back(names[index].c_str());std::vector<uint64_t>ids(count);ck(synTensorRetrieveIds(recipe,cnames.data(),ids.data(),count),"ids");uint64_t bytes=uint64_t(width)*4,pool,workspace=0,workspace_bytes=0;ck(synDeviceMalloc(dev,bytes*count,0,0,&pool),"pool");ck(synWorkspaceGetSize(&workspace_bytes,recipe),"workspace");if(workspace_bytes)ck(synDeviceMalloc(dev,workspace_bytes,0,0,&workspace),"workspace allocation");void*host;ck(synHostMalloc(dev,bytes*count,0,&host),"host");std::fill_n((float*)host,width,.125f);ck(synMemCopyAsync(stream,(uint64_t)host,bytes,pool,HOST_TO_DRAM),"upload");ck(synStreamSynchronize(stream),"upload sync");std::vector<synLaunchTensorInfo>bindings(count);
  for(int i=0;i<count;++i){bindings[i].tensorName=names[ports[i]].c_str();bindings[i].tensorId=ids[i];bindings[i].tensorType=DATA_TENSOR;bindings[i].pTensorAddress=pool+i*bytes;}
  for(int trial=0;trial<5;++trial){std::vector<uint64_t>host_ns,event_ns;for(int rep=0;rep<20;++rep){ck(synEventRecord(start,stream),"record start");auto before=ns();ck(synLaunch(stream,bindings.data(),count,workspace,recipe,0),"launch");auto after=ns();ck(synEventRecord(end,stream),"record end");ck(synEventSynchronize(end),"wait end");uint64_t elapsed;ck(synEventElapsedTime(&elapsed,start,end),"elapsed");host_ns.push_back(after-before);event_ns.push_back(elapsed);}
   std::sort(host_ns.begin(),host_ns.end());std::sort(event_ns.begin(),event_ns.end());log<<"{\"stage\":\"binding_timing\",\"bindings\":"<<count<<",\"nodes\":"<<total-1<<",\"controlled_nodes\":"<<(controlled?"true":"false")<<",\"width\":"<<width<<",\"trial\":"<<trial<<",\"samples\":20,\"host_call_us\":"<<(host_ns[9]+host_ns[10])/2000.<<",\"event_us\":"<<(event_ns[9]+event_ns[10])/2000.<<",\"workspace_bytes\":"<<workspace_bytes<<"}\n";log.flush();}
  ck(synMemCopyAsync(stream,pool,bytes*count,(uint64_t)host,DRAM_TO_HOST),"readback");ck(synStreamSynchronize(stream),"readback wait");size_t bad=0;for(int i=0;i<count;++i)for(int j=0;j<width;++j){float expected=.125f+ports[i]*.03125f;bad+=((float*)host)[i*width+j]!=expected;}log<<"{\"stage\":\"binding_gate\",\"bindings\":"<<count<<",\"controlled_nodes\":"<<(controlled?"true":"false")<<",\"width\":"<<width<<",\"checked\":"<<uint64_t(count)*width<<",\"bad\":"<<bad<<"}\n";log.flush();if(bad)return 5;
  ck(synHostFree(dev,host,0),"host free");if(workspace)ck(synDeviceFree(dev,workspace,0),"workspace free");ck(synDeviceFree(dev,pool,0),"pool free");ck(synRecipeDestroy(recipe),"recipe free");for(auto t:tensors)ck(synTensorDestroy(t),"tensor free");for(auto s:sections)if(s)ck(synSectionDestroy(s),"section free");ck(synGraphDestroy(graph),"graph free");
 }
 ck(synEventDestroy(start),"start free");ck(synEventDestroy(end),"end free");ck(synStreamDestroy(stream),"stream free");ck(synDeviceRelease(dev),"device release");ck(synDestroy(),"destroy");return 0;
}
